examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchCountrySelect(
        {{country.label}},
        selection: $country,
        countries: [{{country.options.0}}, {{country.options.1}}, {{country.options.2}}, {{country.options.3}}, {{country.options.4}}, {{country.options.5}}],
        isClearable: false
    )
    MonarchRegionSelect(
        MonarchRegionSelect.fieldLabel(for: country) ?? "Region",
        selection: $region,
        country: country,
        prompt: "",
        isClearable: false
    )
}
.onChange(of: country) { region = nil }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var country: String? = {{country.value}}
@State private var region: String? = {{region.value}}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var country: String? = "US"
@State private var region: String? = nil

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchCountrySelect(
        "Country",
        selection: $country,
        countries: ["AU", "CA", "FR", "GB", "IN", "US"],
        isClearable: false
    )
    MonarchRegionSelect(
        MonarchRegionSelect.fieldLabel(for: country) ?? "Region",
        selection: $region,
        country: country,
        prompt: "",
        isClearable: false
    )
}
.onChange(of: country) { region = nil }
